<script setup lang="ts">
import { onMounted, ref } from 'vue'
import DataTable from 'primevue/datatable'
import Column from 'primevue/column'
import { stockMasterApi, type ManagedStock, type StockPayload } from '@/services/stockMasterApi'

const stocks = ref<ManagedStock[]>([]), loading = ref(false), saving = ref(false), errorMessage = ref(''), notice = ref('')
const page = ref(0), size = 20, total = ref(0)
const filters = ref({ keyword: '', marketCode: '', useYn: '' as '' | 'true' | 'false' })
const showForm = ref(false), editingId = ref<number | null>(null)
const form = ref<StockPayload>({ stockCode: '', stockName: '', marketCode: null, currencyCode: 'KRW', useYn: true })

function resetForm() { form.value = { stockCode: '', stockName: '', marketCode: null, currencyCode: 'KRW', useYn: true } }
function params() { const p = new URLSearchParams({ page: String(page.value), size: String(size) }); if (filters.value.keyword.trim()) p.set('keyword', filters.value.keyword.trim()); if (filters.value.marketCode.trim()) p.set('marketCode', filters.value.marketCode.trim()); if (filters.value.useYn) p.set('useYn', filters.value.useYn); return p }
async function load() { loading.value = true; errorMessage.value = ''; try { const result = await stockMasterApi.getStocks(params()); stocks.value = result.content; total.value = result.totalElements } catch (e) { errorMessage.value = e instanceof Error ? e.message : '종목 목록을 불러오지 못했습니다.' } finally { loading.value = false } }
async function search() { page.value = 0; await load() }
async function reset() { filters.value = { keyword: '', marketCode: '', useYn: '' }; await search() }
function openCreate() { editingId.value = null; resetForm(); errorMessage.value = ''; showForm.value = true }
function openEdit(stock: ManagedStock) { editingId.value = stock.stockId; form.value = { stockCode: stock.stockCode, stockName: stock.stockName, marketCode: stock.marketCode, currencyCode: stock.currencyCode, useYn: stock.useYn }; errorMessage.value = ''; showForm.value = true }
async function save() { saving.value = true; errorMessage.value = ''; try { const payload = { ...form.value, marketCode: form.value.marketCode?.trim() || null }; if (editingId.value === null) await stockMasterApi.createStock(payload); else await stockMasterApi.updateStock(editingId.value, payload); notice.value = editingId.value === null ? '종목이 등록되었습니다.' : '종목이 수정되었습니다.'; showForm.value = false; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : '저장하지 못했습니다.' } finally { saving.value = false } }
async function toggle(stock: ManagedStock) { if (!window.confirm(`${stock.stockName} 종목을 ${stock.useYn ? '사용 중지' : '사용'}로 변경할까요?`)) return; try { await stockMasterApi.updateStockUsage(stock.stockId, !stock.useYn); notice.value = '사용 상태가 변경되었습니다.'; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : '상태를 변경하지 못했습니다.' } }
async function remove(stock: ManagedStock) { if (!window.confirm(`${stock.stockName} (${stock.stockCode}) 종목을 삭제할까요?`)) return; try { await stockMasterApi.deleteStock(stock.stockId); if (stocks.value.length === 1 && page.value > 0) page.value--; notice.value = '종목이 삭제되었습니다.'; await load() } catch (e) { errorMessage.value = e instanceof Error ? e.message : '삭제하지 못했습니다.' } }
async function onPage(event: { page: number }) { page.value = event.page; await load() }
onMounted(load)
</script>

<template>
  <main class="settings-page"><section class="page-shell">
    <header><div><p>STOCK MASTER</p><h1>주식종목 관리</h1><span>거래 등록에 사용할 종목 기준정보를 관리합니다.</span></div><button class="primary" type="button" @click="openCreate"><i class="pi pi-plus"></i> 종목 등록</button></header>
    <form class="filters" @submit.prevent="search"><input v-model="filters.keyword" placeholder="종목코드 또는 종목명" /><input v-model="filters.marketCode" placeholder="시장코드" /><select v-model="filters.useYn"><option value="">전체 상태</option><option value="true">사용 중</option><option value="false">사용 중지</option></select><button class="primary" type="submit"><i class="pi pi-search"></i> 조회</button><button class="secondary" type="button" @click="reset">초기화</button></form>
    <p v-if="errorMessage && !showForm" class="alert"><i class="pi pi-exclamation-circle"></i>{{ errorMessage }}</p><p v-if="notice" class="toast"><i class="pi pi-check-circle"></i>{{ notice }}</p>
    <section class="panel"><DataTable :value="stocks" dataKey="stockId" lazy paginator :rows="size" :first="page * size" :totalRecords="total" :loading="loading" scrollable :tableStyle="{ minWidth: '880px' }" @page="onPage">
      <Column field="stockCode" header="종목코드" /><Column field="stockName" header="종목명" /><Column field="marketCode" header="시장코드"><template #body="{ data }">{{ data.marketCode || '—' }}</template></Column><Column field="currencyCode" header="통화" /><Column header="상태"><template #body="{ data }"><span class="status" :class="{ off: !data.useYn }">{{ data.useYn ? '사용 중' : '사용 중지' }}</span></template></Column><Column field="updatedAt" header="수정일시" /><Column header="관리"><template #body="{ data }"><div class="actions"><button type="button" title="수정" aria-label="수정" @click="openEdit(data)"><i class="pi pi-pencil"></i></button><button type="button" title="사용 상태 변경" aria-label="사용 상태 변경" @click="toggle(data)"><i :class="data.useYn ? 'pi pi-pause-circle' : 'pi pi-play-circle'"></i></button><button type="button" title="삭제" aria-label="삭제" @click="remove(data)"><i class="pi pi-trash"></i></button></div></template></Column>
      <template #empty><div class="empty">검색 조건에 맞는 종목이 없습니다.</div></template>
    </DataTable></section>
  </section>
  <div v-if="showForm" class="backdrop" @click.self="!saving && (showForm = false)"><section class="modal" role="dialog" aria-modal="true"><header><h2>{{ editingId === null ? '종목 등록' : '종목 수정' }}</h2><button type="button" aria-label="닫기" @click="showForm = false"><i class="pi pi-times"></i></button></header><form @submit.prevent="save"><label>종목코드 <b>*</b><input v-model="form.stockCode" maxlength="30" required /></label><label>종목명 <b>*</b><input v-model="form.stockName" maxlength="200" required /></label><label>시장코드<input v-model="form.marketCode" maxlength="30" /></label><label>통화코드 <b>*</b><input v-model="form.currencyCode" maxlength="10" required /></label><label class="check"><input v-model="form.useYn" type="checkbox" /> 사용 중인 종목</label><p v-if="errorMessage" class="alert">{{ errorMessage }}</p><footer><button class="secondary" type="button" @click="showForm = false">취소</button><button class="primary" type="submit" :disabled="saving">{{ saving ? '저장 중' : '저장' }}</button></footer></form></section></div>
  </main>
</template>

<style scoped>
.settings-page{min-height:calc(100vh - 64px);padding:42px 0;background:#f3f5f1;color:#18211d}.page-shell{width:min(1320px,calc(100% - 48px));margin:auto}.page-shell>header{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.page-shell p{margin:0 0 8px;color:#598077;font-size:11px;font-weight:800;letter-spacing:.14em}.page-shell h1{margin:0;font:500 clamp(34px,4vw,48px) Georgia,serif}.page-shell header span{display:block;margin-top:10px;color:#747e79}.filters,.panel{background:#fff;border:1px solid #dfe4dc;border-radius:18px;box-shadow:0 8px 30px rgba(42,58,49,.04)}.filters{display:flex;gap:10px;align-items:center;padding:18px;margin-bottom:18px}.filters input{flex:1}input,select{height:40px;padding:0 11px;border:1px solid #d8ded9;border-radius:8px;background:#fcfdfb;font:inherit}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:0 15px;border:0;border-radius:9px;font-weight:700}.primary{color:#fff;background:#173f35}.secondary{color:#57625c;background:#eef1ee}.panel{overflow:hidden}.status{padding:4px 8px;border-radius:20px;color:#32705f;background:#e6f3ed;font-size:11px;font-weight:800}.status.off{color:#7b817e;background:#ecefed}.actions{display:flex;gap:5px}.actions button,.modal header button{width:32px;height:32px;border:0;border-radius:7px;color:#52635b;background:#eef1ee}.empty{padding:70px;text-align:center;color:#7b8580}.alert{margin:0 0 14px!important;padding:12px!important;color:#973f34!important;background:#fff0ed;border:1px solid #f2d8d2;border-radius:9px;letter-spacing:0!important}.toast{position:fixed;right:25px;top:90px;z-index:120;padding:13px 17px!important;color:white!important;background:#173f35;border-radius:9px}.backdrop{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:20px;background:rgba(17,29,23,.58)}.modal{width:min(520px,100%);background:white;border-radius:18px;overflow:hidden}.modal header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;border-bottom:1px solid #e5e9e5}.modal h2{margin:0;font:500 27px Georgia,serif}.modal form{display:grid;gap:15px;padding:24px}.modal label{display:grid;gap:7px;font-size:12px;font-weight:700}.modal label b{color:#b45545}.check{display:flex!important;align-items:center}.check input{width:17px;height:17px}.modal footer{display:flex;justify-content:end;gap:8px}@media(max-width:640px){.page-shell{width:calc(100% - 28px)}.page-shell>header,.filters{align-items:stretch;flex-direction:column}.backdrop{padding:0;align-items:end}.modal{border-radius:18px 18px 0 0}}
</style>
